var ALLOWED_PROTOCOLS = ["https:", "http:"];
function assertSafeUrl(url, requireSecure = false) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error(`Invalid URL: ${url}`);
  }
  if (!ALLOWED_PROTOCOLS.includes(parsed.protocol)) {
    throw new Error(`Unsupported URL protocol: ${parsed.protocol}`);
  }
  if (requireSecure && parsed.protocol !== "https:") {
    throw new Error(
      "Refusing to send credentials over an insecure connection. Use HTTPS."
    );
  }
}
function toExactArrayBuffer(data) {
  return data.slice().buffer;
}
function normalizeBody(body) {
  if (body === void 0 || body === null) return void 0;
  if (typeof body === "string") return body;
  if (body instanceof Uint8Array) return toExactArrayBuffer(body);
  return body;
}
async function requestHttp(options) {
  const method = options.method || "GET";
  const url = options.url;
  const headers = options.headers || {};
  assertSafeUrl(url, false);
  try {
    const obs = typeof window !== "undefined" ? window.obsidian : null;
    const reqFn = obs?.requestUrl || (globalThis.app?.vault?.adapter ? globalThis.requestUrl : null);
    if (typeof reqFn === "function") {
      const res = await reqFn({
        url,
        method,
        headers,
        body: options.body instanceof Uint8Array ? toExactArrayBuffer(options.body) : options.body
      });
      return {
        status: res.status,
        text: res.text,
        json: res.json,
        headers: res.headers
      };
    }
  } catch {
  }
  const response = await fetch(url, {
    method,
    headers,
    body: normalizeBody(options.body)
  });
  const text = await response.text();
  let json = null;
  try {
    json = JSON.parse(text);
  } catch {
  }
  return {
    status: response.status,
    text,
    json
  };
}

