function generateMultipartBoundary() {
  const bytes = new Uint8Array(16);
  window.crypto.getRandomValues(bytes);
  let hex = "";
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, "0");
  }
  return `-------MySecretBackupBoundary${hex}`;
}
var GoogleDriveProvider = class {
  constructor(accessToken, folderId = "") {
    this.id = "google-drive";
    this.name = "Google Drive";
    this.accessToken = accessToken.trim();
    this.folderId = folderId.trim();
  }
  async testConnection() {
    if (!this.accessToken) {
      return {
        success: false,
        message: "No se ha introducido un Token de Acceso (OAuth Bearer) para Google Drive."
      };
    }
    try {
      const response = await requestHttp({
        url: "https://www.googleapis.com/drive/v3/about?fields=user,storageQuota",
        method: "GET",
        headers: {
          Authorization: `Bearer ${this.accessToken}`,
          Accept: "application/json"
        }
      });
      if (response.status === 200) {
        const data = response.json;
        const userName = data.user?.displayName || "Usuario de Google";
        const userEmail = data.user?.emailAddress || "";
        return {
          success: true,
          message: `Conexi\xF3n exitosa con Google Drive (${userName}${userEmail ? " - " + userEmail : ""}).`,
          details: data
        };
      } else {
        return {
          success: false,
          message: `Error de Google Drive (C\xF3digo ${response.status}): ${response.text}`
        };
      }
    } catch (err2) {
      return {
        success: false,
        message: `Fallo al conectar con Google Drive: ${err2?.message || String(err2)}`
      };
    }
  }
  async uploadBackup(filename, data) {
    if (!this.accessToken) {
      return {
        success: false,
        message: "Token de acceso no configurado."
      };
    }
    try {
      const boundary = generateMultipartBoundary();
      const metadata = {
        name: filename,
        mimeType: "application/zip",
        description: "Copia de seguridad cifrada de b\xF3veda Obsidian MySecret (AES-256-GCM)"
      };
      if (this.folderId) {
        metadata.parents = [this.folderId];
      }
      const metadataStr = JSON.stringify(metadata);
      const headerPart = `--${boundary}\r
Content-Type: application/json; charset=UTF-8\r
\r
${metadataStr}\r
--${boundary}\r
Content-Type: application/zip\r
\r
`;
      const footerPart = `\r
--${boundary}--`;
      const encoder = new TextEncoder();
      const headerBytes = encoder.encode(headerPart);
      const footerBytes = encoder.encode(footerPart);
      const fullBody = new Uint8Array(headerBytes.length + data.length + footerBytes.length);
      fullBody.set(headerBytes, 0);
      fullBody.set(data, headerBytes.length);
      fullBody.set(footerBytes, headerBytes.length + data.length);
      const response = await requestHttp({
        url: "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart",
        method: "POST",
        headers: {
          Authorization: `Bearer ${this.accessToken}`,
          "Content-Type": `multipart/related; boundary=${boundary}`
        },
        body: toExactArrayBuffer(fullBody)
      });
      if (response.status === 200 || response.status === 201) {
        const resJson = response.json;
        return {
          success: true,
          remoteId: resJson.id,
          bytesUploaded: data.length,
          message: `Copia de seguridad subida correctamente a Google Drive (ID: ${resJson.id}).`
        };
      } else {
        return {
          success: false,
          message: `Error al subir a Google Drive (C\xF3digo ${response.status}): ${response.text}`
        };
      }
    } catch (err2) {
      return {
        success: false,
        message: `Error de red al subir a Google Drive: ${err2?.message || String(err2)}`
      };
    }
  }
};

