var WebDAVProvider = class {
  constructor(serverUrl, username = "", password = "", remotePath = "MySecretBackups") {
    this.id = "webdav";
    this.name = "WebDAV (Nextcloud / Box / pCloud / NAS)";
    this.serverUrl = serverUrl.trim().replace(/\/+$/, "");
    this.username = username.trim();
    this.password = password.trim();
    this.remotePath = remotePath.trim().replace(/^\/+|\/+$/g, "") || "MySecretBackups";
  }
  /**
   * SECURITY: the Basic `Authorization` header carries the WebDAV password in
   * base64 (i.e. effectively in cleartext). It must never travel over plain
   * HTTP, so an insecure server URL is rejected outright.
   */
  assertSecureTransport() {
    assertSafeUrl(this.serverUrl, true);
  }
  getAuthHeader() {
    if (!this.username) return "";
    try {
      const creds = `${this.username}:${this.password}`;
      if (typeof window !== "undefined" && window.btoa) {
        return `Basic ${window.btoa(unescape(encodeURIComponent(creds)))}`;
      }
      return `Basic ${Buffer.from(creds).toString("base64")}`;
    } catch {
      return "";
    }
  }
  async testConnection() {
    if (!this.serverUrl) {
      return {
        success: false,
        message: "No se ha configurado la URL del servidor WebDAV."
      };
    }
    try {
      this.assertSecureTransport();
    } catch (err2) {
      return {
        success: false,
        message: err2?.message || String(err2)
      };
    }
    try {
      const headers = {};
      const auth = this.getAuthHeader();
      if (auth) headers["Authorization"] = auth;
      let response;
      try {
        response = await requestHttp({
          url: this.serverUrl,
          method: "PROPFIND",
          headers: {
            ...headers,
            Depth: "0"
          }
        });
      } catch {
        response = await requestHttp({
          url: this.serverUrl,
          method: "OPTIONS",
          headers
        });
      }
      if (response.status >= 200 && response.status < 400) {
        return {
          success: true,
          message: `Conexi\xF3n exitosa con el servidor WebDAV (${this.serverUrl}).`
        };
      } else {
        return {
          success: false,
          message: `Servidor WebDAV respondi\xF3 con c\xF3digo ${response.status}: ${response.text}`
        };
      }
    } catch (err2) {
      return {
        success: false,
        message: `Fallo de conexi\xF3n al servidor WebDAV: ${err2?.message || String(err2)}`
      };
    }
  }
  async uploadBackup(filename, data) {
    if (!this.serverUrl) {
      return {
        success: false,
        message: "URL del servidor WebDAV no configurada."
      };
    }
    try {
      this.assertSecureTransport();
    } catch (err2) {
      return {
        success: false,
        message: err2?.message || String(err2)
      };
    }
    try {
      const headers = {
        "Content-Type": "application/zip"
      };
      const auth = this.getAuthHeader();
      if (auth) headers["Authorization"] = auth;
      const targetDirUrl = `${this.serverUrl}/${encodeURIComponent(this.remotePath)}`;
      try {
        await requestHttp({
          url: targetDirUrl,
          method: "MKCOL",
          headers: auth ? { Authorization: auth } : {}
        });
      } catch {
      }
      const fileUrl = `${targetDirUrl}/${encodeURIComponent(filename)}`;
      const response = await requestHttp({
        url: fileUrl,
        method: "PUT",
        headers,
        body: toExactArrayBuffer(data)
      });
      if (response.status === 200 || response.status === 201 || response.status === 204) {
        return {
          success: true,
          remotePath: `${this.remotePath}/${filename}`,
          bytesUploaded: data.length,
          message: `Copia de seguridad subida correctamente a WebDAV (${this.remotePath}/${filename}).`
        };
      } else {
        return {
          success: false,
          message: `Error al subir a WebDAV (C\xF3digo ${response.status}): ${response.text}`
        };
      }
    } catch (err2) {
      return {
        success: false,
        message: `Error de red al subir a WebDAV: ${err2?.message || String(err2)}`
      };
    }
  }
};

