var LocalSyncProvider = class {
  constructor(destinationPath) {
    this.id = "local-sync";
    this.name = "Carpeta Sincronizada (MEGA / Drive / OneDrive de Escritorio)";
    this.destinationPath = destinationPath.trim();
  }
  getFs() {
    try {
      return window.require ? window.require("fs") : require("fs");
    } catch {
      return null;
    }
  }
  getPathModule() {
    try {
      return window.require ? window.require("path") : require("path");
    } catch {
      return null;
    }
  }
  async testConnection() {
    if (!this.destinationPath) {
      return {
        success: false,
        message: "No se ha especificado la ruta de la carpeta de sincronizaci\xF3n."
      };
    }
    const fs = this.getFs();
    if (!fs) {
      return {
        success: false,
        message: "La escritura directa en carpetas locales solo est\xE1 disponible en Obsidian para Escritorio."
      };
    }
    try {
      if (!fs.existsSync(this.destinationPath)) {
        fs.mkdirSync(this.destinationPath, { recursive: true });
      }
      const testFile = this.getPathModule()?.join(this.destinationPath, ".mysecret_write_test") || `${this.destinationPath}/.mysecret_write_test`;
      fs.writeFileSync(testFile, "test");
      fs.unlinkSync(testFile);
      return {
        success: true,
        message: `Ruta accesible y con permisos de escritura: ${this.destinationPath}`
      };
    } catch (err2) {
      return {
        success: false,
        message: `Error al acceder a la carpeta '${this.destinationPath}': ${err2?.message || String(err2)}`
      };
    }
  }
  async uploadBackup(filename, data) {
    if (!this.destinationPath) {
      return {
        success: false,
        message: "Ruta de destino no configurada."
      };
    }
    const fs = this.getFs();
    if (!fs) {
      return {
        success: false,
        message: "Esta funci\xF3n requiere Obsidian de escritorio para acceder a carpetas del sistema."
      };
    }
    try {
      if (!fs.existsSync(this.destinationPath)) {
        fs.mkdirSync(this.destinationPath, { recursive: true });
      }
      const pathMod = this.getPathModule();
      const safeName = sanitizeVaultRelativePath(filename);
      if (!safeName.safe || safeName.path.includes("/")) {
        return {
          success: false,
          message: `Nombre de archivo de copia de seguridad no v\xE1lido: ${safeName.reason || "la ruta contiene separadores"}`
        };
      }
      const targetFilePath = pathMod ? pathMod.join(this.destinationPath, safeName.path) : `${this.destinationPath}/${safeName.path}`;
      const buffer = Buffer.from(data.buffer, data.byteOffset, data.byteLength);
      fs.writeFileSync(targetFilePath, buffer);
      return {
        success: true,
        remotePath: targetFilePath,
        bytesUploaded: data.length,
        message: `Copia de seguridad guardada exitosamente en: ${targetFilePath}`
      };
    } catch (err2) {
      return {
        success: false,
        message: `Error al escribir en la carpeta local: ${err2?.message || String(err2)}`
      };
    }
  }
};

// src/backup/cloud/index.ts
function createCloudProvider(settings) {
  switch (settings.provider) {
    case "google-drive":
      return new GoogleDriveProvider(
        settings.googleDrive.accessToken,
        settings.googleDrive.folderId
      );
    case "onedrive":
      return new OneDriveProvider(
        settings.oneDrive.accessToken,
        settings.oneDrive.folderPath
      );
    case "webdav":
      return new WebDAVProvider(
        settings.webdav.serverUrl,
        settings.webdav.username,
        settings.webdav.password,
        settings.webdav.remotePath
      );
    case "local-sync":
      return new LocalSyncProvider(
        settings.localSync.destinationPath
      );
    case "none":
    default:
      return null;
  }
}

