var import_obsidian7 = require("obsidian");
var FolderPickerModal = class extends import_obsidian7.FuzzySuggestModal {
  constructor(app, excludedFolders, onChoose) {
    super(app);
    this.onChooseCallback = onChoose;
    this.setPlaceholder(t("folderPicker.placeholder"));
    const normalize = (p) => p.replace(/^[/\\]+/, "").replace(/[/\\]+$/, "").replace(/\\/g, "/");
    const currentExcludedSet = new Set(excludedFolders.map((f) => normalize(f)));
    const allFiles = this.app.vault.getAllLoadedFiles();
    this.folders = allFiles.filter((file) => {
      if (!(file instanceof import_obsidian7.TFolder)) return false;
      if (typeof file.isRoot === "function" && file.isRoot()) return false;
      const norm = normalize(file.path);
      return norm.length > 0 && norm !== "/";
    }).filter((folder) => !currentExcludedSet.has(normalize(folder.path))).sort((a, b) => a.path.localeCompare(b.path));
    this.emptyStateText = t("folderPicker.emptyText");
  }
  getItems() {
    return this.folders;
  }
  getItemText(folder) {
    return folder.path;
  }
  renderSuggestion(item, el) {
    super.renderSuggestion(item, el);
    const iconSpan = el.createSpan({ cls: "mysecret-folder-suggestion-icon" });
    (0, import_obsidian7.setIcon)(iconSpan, "folder");
    el.prepend(iconSpan);
    el.addClass("mysecret-folder-suggestion-item");
  }
  onChooseItem(folder, _evt) {
    this.onChooseCallback(folder);
  }
};

// src/biometrics/bridge-url.ts
function validateBridgeUrl(rawUrl) {
  const reject = (reason) => ({ valid: false, url: "", reason });
  const trimmed = (rawUrl || "").trim();
  if (!trimmed) {
    return reject("La URL del puente est\xE1 vac\xEDa.");
  }
  if (/^\s*(javascript|data|file|blob|about|vbscript):/i.test(trimmed)) {
    return reject("El esquema de la URL no es permitido. Usa una URL https:// de Cloudflare Pages.");
  }
  let candidate = trimmed;
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(candidate)) {
    candidate = "https://" + candidate.replace(/^\/+/, "");
  }
  let parsed;
  try {
    parsed = new URL(candidate);
  } catch {
    return reject("La URL del puente no tiene un formato v\xE1lido.");
  }
  if (parsed.protocol !== "https:") {
    if (parsed.protocol === "http:" && parsed.hostname === "localhost") {
    } else {
      return reject("La URL del puente debe usar HTTPS.");
    }
  }
  if (parsed.username || parsed.password) {
    return reject("La URL del puente no debe incluir credenciales.");
  }
  if (!parsed.hostname) {
    return reject("La URL del puente no incluye un dominio.");
  }
  const normalized = `${parsed.origin}${parsed.pathname.replace(/\/+$/, "")}`;
  return { valid: true, url: normalized, reason: null };
}

// src/ui/settings-tab.ts
function debounce(fn, ms) {
  let timer = null;
  return (...args) => {
    if (timer !== null) window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      timer = null;
      void fn(...args);
    }, ms);
  };
}
